<?php
declare(strict_types=1);
require_once __DIR__.'/MovieBanks.php';
function movieBankPanel(string $kind,array $info):string {
 $title=$kind==='title';$plural=$title?'Titles':'IDs';$word=$title?'Title':'ID';$example=$title?'Watch {movie_name} ({year}) Online':'watch-{movie_name}-{year}-hd';
 $count=(int)($info['count']??0);$saved=isset($info['saved_at'])?(new DateTimeImmutable($info['saved_at']))->setTimezone(new DateTimeZone('Asia/Dhaka'))->format('d F Y, h:i:s A').' (Bangladesh time)':'Not saved yet';
 return '<section class="panel"><h2>Movie '.$word.' Templates</h2><p>Use <code>{movie_name}</code> and <code>{year}</code>.</p><div class="notice success" id="'.$kind.'-bank-summary">'.number_format($count).' saved '.strtolower($plural).' · '.h($saved).'</div><p><a class="button secondary" id="'.$kind.'-bank-export" href="/movies/'.($title?'titles':'ids').'/export" '.(!$count?'hidden':'').'>Download Saved '.$plural.'</a></p><form id="'.$kind.'-bank-form" class="stack" action="/api/'.$kind.'-bank" method="post" enctype="multipart/form-data">'.tokenField().'<input type="hidden" name="generator" value="movie"><input type="hidden" name="action" value="import"><label>Paste Movie '.$word.' Templates<textarea name="'.$kind.'_templates" rows="7" placeholder="'.h($example).'"></textarea></label><label>Or Upload '.$plural.' TXT<input type="file" name="'.$kind.'_file" accept=".txt,text/plain"><small>One template per line. UTF-8 TXT, up to 128 MB.</small></label><label>Save Mode<select name="'.$kind.'_mode"><option value="append">Add to saved '.strtolower($plural).'</option><option value="replace">Replace movie '.strtolower($plural).'</option></select></label><button class="primary" id="save-'.$kind.'-bank">Save '.$plural.'</button><div id="'.$kind.'-bank-result" class="notice" hidden></div></form></section>';
}
function moviesPage():string {
 $titleBank=new MovieTitleBank(db());$idBank=new MovieIdBank(db());$titleInfo=$titleBank->info();$idInfo=$idBank->info();
 $body='<h1>Movies</h1><div class="workspace"><section class="panel"><h2>Build Your Movie Batch</h2><form id="generate-form" class="stack" data-generator="movie">'.tokenField().'<input type="hidden" name="generator" value="movie"><input type="hidden" name="event_type" value="Movie"><input type="hidden" name="id_source" value="saved">'.input('Movie Name','event','text','','').'<label>Year<input name="year" type="text" inputmode="numeric" pattern="[1-9][0-9]{3}" maxlength="4" placeholder="2026" required></label><label>Domain Names (Optional)<textarea name="url_domains" rows="4" placeholder="https://example.com/"></textarea><small>One domain or URL per line.</small></label><label class="toggle-row"><span>Enable Domain Randomizer</span><input type="checkbox" name="randomize_domains" value="1" role="switch"><span class="toggle-track" aria-hidden="true"></span></label>'.savedXmlControl((int)$_SESSION['user_id']).input('Movie URL','event_url','url','','The destination URL in your template redirect.').'<label>Total Files &amp; URLs<input type="number" name="count" min="1" max="1000" step="1" required></label><p class="hint">Uses the HTML and images saved in Settings. Upload movie titles and IDs below. Titles and IDs are picked randomly from unused saved templates for this movie.</p><button class="primary large" id="generate">'.activitySpinner(true).'<span class="generate-label">Generate Files &amp; URLs</span><span class="generate-arrow" aria-hidden="true">↗</span></button></form></section>'.generatorOutputHtml();
 $body.='<div class="workspace">'.movieBankPanel('title',$titleInfo).movieBankPanel('id',$idInfo).'</div>';
 return $body;
}
